#cookiescript_injected_wrapper { position: fixed; padding: 0px; width: 100%; inset: 0px; z-index: 999996; background-color: rgba(17, 17, 17, 0.5) !important; }
#cookiescript_injected { bottom: 0px; left: 0px; right: 0px; position: fixed; padding: 15px 20px 10px; width: 100%; display: flex; flex-direction: column; text-align: center; margin: 0px; align-items: center; max-height: 85%; overflow-y: auto; }
.cookiescript-extra-links { padding-top: 0px; }
.cookiescript-extra-links a { margin-left: 0px; margin-right: 25px; }
#cookiescript_copyright { line-height: 1; text-align: center; }
#cookiescript_buttons { justify-content: center; flex-wrap: wrap; margin: 0px 0px 10px; }
#cookiescript_manage_wrap { margin: 0px 0px 14px; }
#cookiescript_header { padding: 3px 0px 8px; margin: 0px 60px; text-align: center; }
#cookiescript_checkboxs { margin: -5px auto 8px; display: flex; flex-wrap: wrap; }
.cookiescript_checkbox { margin: 0px; }
#cookiescript_accept, #cookiescript_reject, #cookiescript_save { margin: 5px 7px; flex-shrink: 1; padding: 0px 23px; white-space: normal; }
#cookiescript_description { margin: 0px auto 8px; text-align: center; max-width: 600px; }
.cookiescript_checkbox_label { padding: 0px; margin: 0px 10px 0px -2px; }
#cookiescript_cookietablewrap { transition: height 300ms, min-height 300ms, max-height 300ms, opacity 200ms 300ms; }
#cookiescript_cookietablewrap.cookiescript_hidden { transition: height 300ms, min-height 300ms, max-height 300ms, opacity 200ms; }
@media only screen and (max-width: 440px) {
  #cookiescript_injected { bottom: 0px; left: 0px; width: 100%; padding: 15px; text-align: left; align-items: center; }
  #cookiescript_description { text-align: left; }
  #cookiescript_description, #cookiescript_buttons, #cookiescript_manage_wrap, #cookiescript_checkboxs { margin-bottom: 8px; }
  #cookiescript_header { padding-top: 5px; margin-left: 0px; text-align: left; align-self: baseline; }
  #cookiescript_show_all_partners_button { width: 100%; }
  #cookiescript_buttons { flex-wrap: wrap; width: 100%; }
